<?php
require_once __DIR__.'/../includes/resources.php';require_login();
$user=current_user();$uid=(int)$user['user_id'];$bookmarks=user_bookmarks($uid,4);
$favorites=db_all('SELECT c.* FROM categories c JOIN user_favorites f ON f.category_id=c.category_id WHERE f.user_id=? AND c.is_active=1 ORDER BY c.sort_order',[$uid]);
$activity=db_all("SELECT * FROM activity_logs WHERE user_id=? AND action IN ('sign_in','registered','profile_updated','bookmarked','bookmark_removed','note_updated','rated','fan_submitted','feedback_sent','password_reset') ORDER BY log_id DESC LIMIT 7",[$uid]);
$recommended=db_all("SELECT c.*,cat.name category FROM content c JOIN user_favorites f ON f.category_id=c.category_id JOIN categories cat ON cat.category_id=c.category_id WHERE f.user_id=? AND c.visibility='published' AND cat.is_active=1 ORDER BY c.created_at DESC LIMIT 4",[$uid]);
$page_title='My dashboard';require __DIR__.'/../includes/user_header.php';
?>
